  insert into public.lesson_blocks (lesson_id, block_type, position, content) values
  (lesson_uuid,'heading',0,'{"eyebrow":"День 1 из 14","title":"Что такое тестирование"}'),
  (lesson_uuid,'text',1,'{"markdown":"Сегодня ты поймёшь, зачем команде тестирование, чем оно шире поиска багов и почему в вакансиях часто пишут «QA-инженер». Новые слова будем сначала разбирать по-человечески, а потом давать точное значение."}'),
  (lesson_uuid,'video',2,'{"title":"Приветствие Артура","description":"Короткое необязательное приветствие.","required":false,"blocksNext":false}'),
  (lesson_uuid,'heading',3,'{"title":"Зачем вообще проверять продукт"}'),
  (lesson_uuid,'text',4,'{"markdown":"Представь приложение банка. Человек переводит деньги, но после нажатия кнопки не понимает, ушёл ли платёж. Проблема может быть в коде, в неясном сообщении или в требовании. Тестирование помогает команде получить информацию о таких рисках до того, как они затронут многих пользователей."}'),
  (lesson_uuid,'definition',5,'{"term":"Тестирование ПО (testing)","text":"По ISTQB это набор действий жизненного цикла, связанных со статическим и динамическим тестированием. Проще: мы исследуем продукт и его материалы, чтобы понять его состояние, найти дефекты и снизить неопределённость о качестве."}'),
  (lesson_uuid,'example',6,'{"title":"Два результата тестирования","expected":"После успешной оплаты пользователь видит номер заказа.","actual":"Деньги списались, но экран остаётся на форме оплаты.","conclusion":"Это не приговор «в коде баг». Сначала QA проверит требование, логи и повторяемость, затем сообщит команде о наблюдении."}'),
  (lesson_uuid,'question',7,'{"questionType":"multiple_choice","question":"Что может быть целью тестирования?","options":["Получить информацию о качестве и рисках","Найти дефекты","Доказать, что в продукте нет ошибок","Проверить, соответствует ли поведение важным ожиданиям"],"correctAnswers":[0,1,3],"explanation":"Тестирование помогает находить дефекты, оценивать качество и снижать риск. Оно не может доказать полное отсутствие дефектов."}'),
  (lesson_uuid,'heading',8,'{"title":"Простая модель: ожидание и фактический результат"}'),
  (lesson_uuid,'text',9,'{"markdown":"Для одной проверки мы формулируем ожидаемый результат, выполняем действие и наблюдаем фактический результат. Сравнение полезно, но это только одна часть тестирования: иногда важно проверить удобство, скорость, безопасность или неясность требования ещё до запуска программы."}'),
  (lesson_uuid,'important',10,'{"title":"Частая ошибка новичка","text":"Не называй любой неожиданный результат багом сразу. Сначала уточни test basis: требование, макет, правило или согласованное ожидание. Возможно, ожидание было неверным или требование неполным."}'),
  (lesson_uuid,'question',11,'{"question":"В форме пароль из 50 символов принимается, хотя в требовании указан максимум 30. Что лучше сделать первым?","options":["Сразу назвать это багом без деталей","Сверить наблюдение с требованием и зафиксировать шаги, ожидаемый и фактический результат","Попросить пользователя не вводить длинные пароли","Игнорировать ситуацию"],"correctIndex":1,"explanation":"Требование даёт проверяемое ожидание. После сверки QA может подготовить понятный отчёт о дефекте."}'),
  (lesson_uuid,'heading',12,'{"title":"QA, testing и QC: почему это не одно и то же"}'),
  (lesson_uuid,'text',13,'{"markdown":"Testing — деятельность по тестированию. Quality assurance, или QA, — более широкий подход к уверенности в том, что процессы и продукт способны дать нужное качество: например, ясные требования, ревью и улучшение процесса. Quality control, или QC, фокусируется на проверке результата относительно требований. В индустрии роль человека, который много тестирует и помогает качеству, часто называют QA-инженером. Это привычное название роли, а не синоним всех трёх понятий."}'),
  (lesson_uuid,'diagram',14,'{"title":"Как QA участвует в работе","steps":["Требование или макет","Вопросы и риски","Проверки продукта","Наблюдения и обратная связь","Решение команды"]}'),
  (lesson_uuid,'question',15,'{"questionType":"multiple_choice","question":"Какие действия ближе к quality assurance?","options":["Уточнить неполное требование до разработки","Проверить готовую форму регистрации","Улучшить правило передачи требований команде","Гарантировать, что дефектов нет"],"correctAnswers":[0,2],"explanation":"QA направлено на предотвращение проблем через процессы и сотрудничество. Проверка готовой формы — пример testing; абсолютную гарантию дать нельзя."}'),
  (lesson_uuid,'heading',16,'{"title":"Ошибка, дефект и отказ"}'),
  (lesson_uuid,'definition',17,'{"term":"Error, defect, failure","text":"Error — человеческое действие или решение, которое может привести к неверному результату. Defect — недостаток в артефакте, например в требовании, коде или настройке. Failure — наблюдаемое отклонение работы продукта от ожидаемого поведения при выполнении."}'),
  (lesson_uuid,'example',18,'{"title":"Одна цепочка причин","expected":"Скидка 10% применяется к заказу.","actual":"На экране скидка равна 0%.","conclusion":"Разработчик мог ошибиться при расчёте (error), в код попал неверный оператор (defect), а пользователь увидел неправильную сумму (failure). Не каждая ошибка обязательно приводит к наблюдаемому отказу."}'),
  (lesson_uuid,'question',19,'{"question":"Как точнее назвать ситуацию: пользователь видит неверную сумму скидки?","options":["Failure: наблюдаемое неправильное поведение","Только error","Доказательство, что QA не нужен","Всегда severity Critical"],"correctIndex":0,"explanation":"Неверное поведение, наблюдаемое при работе продукта, соответствует понятию failure. Причину и серьёзность ещё нужно исследовать."}'),
  (lesson_uuid,'heading',20,'{"title":"Как мыслит тестировщик"}'),
  (lesson_uuid,'text',21,'{"markdown":"QA не ограничивается счастливым сценарием. Он спрашивает: что будет при пустом поле, длинном имени, двойном клике, плохом интернете, повторной отправке формы? Это не недоверие к разработчику, а способ увидеть риски для пользователя и команды."}'),
  (lesson_uuid,'summary',22,'{"title":"Главное из урока","items":[["Testing","Исследование продукта и связанных материалов, которое даёт информацию о качестве и рисках."],["QA","Деятельность по обеспечению уверенности в процессах и качестве; шире одного теста."],["Expected result","То, что должно произойти по test basis."],["Actual result","То, что произошло в конкретной проверке."],["Defect","Недостаток в артефакте."],["Failure","Наблюдаемое отклонение поведения продукта."]],"points":["Тестирование не доказывает отсутствие всех дефектов.","QA-инженер — распространённое название роли, а не определение QA.","Сначала проверяем основание ожидания, затем делаем вывод.","Вопрос «а что будет, если?» помогает находить риски."]}'),
  (lesson_uuid,'question',23,'{"questionType":"multiple_choice","question":"Выберите все верные утверждения по уроку.","options":["Testing может давать информацию о рисках","QA и testing всегда одно и то же","Defect может находиться не только в коде","Failure — это наблюдаемое неправильное поведение"],"correctAnswers":[0,2,3],"explanation":"Testing и QA связаны, но не тождественны. Дефект возможен в требовании, коде, данных или конфигурации; failure наблюдается при работе продукта."}');
